let input = "";
try {
  input = $fromAI("requested_timeframe");
} catch (e) {
  input = $input.first()?.json?.query?.utterance || "";
}

// Simulated provider availability rules
const requestedLower = String(input || "").toLowerCase();

if (requestedLower.includes("sunday") || requestedLower.includes("weekend")) {
  return JSON.stringify({
    status: "UNAVAILABLE",
    reason: "Clinic is closed on weekends. Available days are Monday through Friday, 8:00 AM - 5:00 PM.",
    suggested_slots: ["Next Tuesday at 10:00 AM", "Next Wednesday at 2:00 PM"]
  });
}

return JSON.stringify({
  status: "CONFIRMED",
  action: "APPOINTMENT_RESCHEDULED",
  details: "Appointment successfully moved to the requested timeframe.",
  confirmation_code: "HN-RESCHED-" + Math.floor(100000 + Math.random() * 900000)
});

let rawInput = "";
try {
  rawInput = $fromAI("user_request");
} catch (e) {
  rawInput = $input.first()?.json?.query?.utterance || "";
}

const input = String(rawInput || "").toLowerCase();

// Scenario A: Missing Location or General Query -> Return Location & Slot Options
if (!input.includes("downtown") && !input.includes("westside")) {
  return JSON.stringify({
    status: "SELECTION_REQUIRED",
    message: "Please specify your preferred clinic location and choose an open slot.",
    available_locations: ["Downtown Clinic", "Westside Medical"],
    suggested_slots: [
      { id: "SLOT_101", location: "Downtown Clinic", time: "Tuesday, Sep 15 at 9:00 AM" },
      { id: "SLOT_102", location: "Downtown Clinic", time: "Tuesday, Sep 15 at 2:00 PM" },
      { id: "SLOT_201", location: "Westside Medical", time: "Wednesday, Sep 16 at 10:30 AM" }
    ]
  });
}

// Scenario B: Valid Selection -> Confirm Reservation
return JSON.stringify({
  status: "CONFIRMED",
  location: input.includes("westside") ? "Westside Medical" : "Downtown Clinic",
  time: "Requested Slot",
  confirmation_code: "HN-RESCHED-" + Math.floor(100000 + Math.random() * 900000)
});
